# Source: src/vbll/train.py (original VBLL whitening)
def clamp_abs_(x: torch.Tensor, max_abs: float):
    if max_abs and max_abs > 0:
        return torch.clamp(x, -max_abs, max_abs)
    return x

def whitening_params(x: torch.Tensor, eps: float = 1e-3):
    x64 = x.detach().double()
    mean = x64.mean(dim=0)
    xc = x64 - mean

    n = xc.shape[0]
    sigma = (xc.T @ xc) / max(1, (n - 1))

    evals, evecs = torch.linalg.eigh(sigma)
    evals = torch.clamp(evals, min=eps)

    w = evecs @ torch.diag(evals.rsqrt()) @ evecs.T
    return mean.to(x.dtype), w.to(x.dtype)

def whiten(x: torch.Tensor, mean: torch.Tensor, w: torch.Tensor):
    return (x - mean) @ w

