import numpy as np


import torch


import torch.nn as nn


import torch.optim as optim


import vbll




from sklearn.preprocessing import StandardScaler


from torch.distributions import Normal


from torch.utils.data import DataLoader, TensorDataset


def should_run_epoch_eval(epoch: int, total_epochs: int, every_n_epochs: int) -> bool:
    return (epoch % every_n_epochs == 0) or (epoch == total_epochs)


def assert_finite(name: str, tensor: torch.Tensor):
    if not torch.isfinite(tensor).all():
        bad = (~torch.isfinite(tensor)).sum().item()
        safe = torch.nan_to_num(tensor.detach(), nan=0.0, posinf=0.0, neginf=0.0)
        raise RuntimeError(
            f"{name} has {bad} non-finite values. "
            f"min={safe.min().item():.3e} max={safe.max().item():.3e} mean={safe.mean().item():.3e}"
        )


class VBLLRegressor(nn.Module):
    def __init__(self, input_dim, hidden_dim, hidden_layers, activation_cls, reg_weight, prior_scale=1.0, wishart_scale=0.1):
        super().__init__()

        layers = [nn.Linear(input_dim, hidden_dim), activation_cls()]
        for _ in range(hidden_layers - 1):
            layers.append(nn.Linear(hidden_dim, hidden_dim))
            layers.append(activation_cls())
        self.backbone = nn.Sequential(*layers)

        self.out_layer = vbll.Regression(
            hidden_dim,
            1,
            reg_weight,
            prior_scale=prior_scale,
            wishart_scale=wishart_scale,
        )

    def forward(self, x):
        return self.out_layer(self.backbone(x))


@torch.no_grad()
def rmse(pred_mean_raw, y_raw):
    return torch.sqrt(torch.mean((pred_mean_raw - y_raw.squeeze(-1)) ** 2)).item()


@torch.no_grad()
def vbll_nll_raw(vbll_out, y_raw, y_mean, y_std, eps=1e-12):
    pred = vbll_out.predictive
    mu = pred.mean.squeeze(-1)

    cov = pred.covariance
    if cov.dim() == 3:
        var = cov[:, 0, 0]
    else:
        var = cov.squeeze(-1).squeeze(-1) if cov.dim() > 1 else cov
    var = torch.clamp(var, min=eps)

    mu_raw = mu * y_std + y_mean
    var_raw = var * (y_std ** 2)
    dist = Normal(loc=mu_raw, scale=torch.sqrt(torch.clamp(var_raw, min=eps)))
    return (-dist.log_prob(y_raw.squeeze(-1))).mean().item()


@torch.no_grad()
def eval_vbll(model, x_ms, y_raw, y_mean, y_std):
    model.eval()
    out = model(x_ms)
    mu_ms = out.predictive.mean.squeeze(-1)
    mu_raw = mu_ms * y_std + y_mean
    return rmse(mu_raw, y_raw), vbll_nll_raw(out, y_raw, y_mean, y_std)


def train_one_split(
    model,
    train_loader,
    x_train_ms,
    x_test_ms,
    y_train_raw,
    y_test_raw,
    y_mean,
    y_std,
    num_epochs,
    lr,
    wd,
    clip_val,
    split_idx=0,
    log_to_wandb=False,
    run=None,
    debug_nan=False,
    epoch_eval_csv_path=None,
    epoch_eval_every_epochs=1,
):
    param_list = [
        {"params": model.backbone.parameters(), "weight_decay": wd},
        {"params": model.out_layer.parameters(), "weight_decay": 0.0},
    ]
    optimizer = optim.AdamW(param_list, lr=lr)

    train_seconds = 0.0
    training_history = []
    epoch_eval_every_epochs = max(1, int(epoch_eval_every_epochs))
    epoch_eval_csv_file = None
    epoch_eval_csv_writer = None
    if epoch_eval_csv_path is not None:
        epoch_eval_csv_file = open(epoch_eval_csv_path, "w", newline="")
        epoch_eval_csv_writer = csv.writer(epoch_eval_csv_file)
        epoch_eval_csv_writer.writerow(["epoch", "train_loss", "train_rmse", "train_nll", "test_rmse", "test_nll"])

    for epoch in range(1, num_epochs + 1):
        epoch_t0 = time.perf_counter()
        model.train()
        losses = []

        for xb, yb in train_loader:
            if debug_nan:
                assert_finite("xb(batch)", xb)
                assert_finite("yb(batch)", yb)

            optimizer.zero_grad()
            out = model(xb)
            loss = out.train_loss_fn(yb)

            if debug_nan and not torch.isfinite(loss):
                raise RuntimeError(f"Non-finite loss at epoch={epoch}, split={split_idx}")

            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), clip_val)
            optimizer.step()
            losses.append(loss.item())

        if log_to_wandb and run is not None:
            run[f"train/split_{split_idx}/vbll_train_loss"].append(float(np.mean(losses)))

        should_log_to_wandb = (
            log_to_wandb
            and run is not None
            and (epoch % max(1, (num_epochs // 10)) == 0 or epoch == 1)
        )
        should_write_epoch_eval_csv = (
            epoch_eval_csv_writer is not None
            and should_run_epoch_eval(epoch, num_epochs, epoch_eval_every_epochs)
        )
        if should_log_to_wandb or should_write_epoch_eval_csv:
            tr_rmse, tr_nll = eval_vbll(model, x_train_ms, y_train_raw, y_mean, y_std)
            te_rmse, te_nll = eval_vbll(model, x_test_ms, y_test_raw, y_mean, y_std)

            if should_write_epoch_eval_csv:
                epoch_eval_csv_writer.writerow([epoch, float(np.mean(losses)), tr_rmse, tr_nll, te_rmse, te_nll])
                epoch_eval_csv_file.flush()

            if log_to_wandb and run is not None:
                run[f"train/split_{split_idx}/rmse"].append(tr_rmse)
                run[f"train/split_{split_idx}/nll"].append(tr_nll)
                run[f"test/split_{split_idx}/rmse"].append(te_rmse)
                run[f"test/split_{split_idx}/nll"].append(te_nll)

        if next(model.parameters()).is_cuda: torch.cuda.synchronize(next(model.parameters()).device)
        training_history.append(dict(epoch=epoch, train_loss=float(np.mean(losses))))
        epoch_elapsed = time.perf_counter() - epoch_t0
        train_seconds += epoch_elapsed

    train_eval_t0 = time.perf_counter()
    tr_rmse, tr_nll = eval_vbll(model, x_train_ms, y_train_raw, y_mean, y_std)
    train_eval_seconds = time.perf_counter() - train_eval_t0

    test_eval_t0 = time.perf_counter()
    te_rmse, te_nll = eval_vbll(model, x_test_ms, y_test_raw, y_mean, y_std)
    test_eval_seconds = time.perf_counter() - test_eval_t0
    if epoch_eval_csv_file is not None:
        epoch_eval_csv_file.close()
    return tr_rmse, tr_nll, te_rmse, te_nll, {
        "training_history": training_history,
        "train_seconds": train_seconds,
        "train_eval_seconds": train_eval_seconds,
        "test_eval_seconds": test_eval_seconds,
        "total_seconds": train_seconds + train_eval_seconds + test_eval_seconds,
    }



# --- Experiment I/O: these helpers are intentionally local to every script. ---
def experiment_setup():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--data", default=CONFIG["data_path"])
    parser.add_argument("--output", default=CONFIG["output_root"], help="Exact run directory; defaults create a unique subdirectory")
    parser.add_argument("--device", default=CONFIG["device"])
    parser.add_argument("--epochs", type=int, help="Optional training-budget override for smoke tests")
    parser.add_argument("--learning-rate", type=float, help="Override the model learning rate")
    parser.add_argument("--repulsion-strength", type=float, help="Override repulsion coefficient for repulsive methods")
    parser.add_argument("--reuse-stage1", help="BDKN stage1.pt to reuse; deep ensemble only")
    args = parser.parse_args()
    cfg = dict(CONFIG)
    if args.learning_rate is not None:
        if not np.isfinite(args.learning_rate) or args.learning_rate <= 0: parser.error("Learning rate must be finite and positive")
        cfg["lr"] = args.learning_rate
    if args.repulsion_strength is not None:
        if "repulsion_strength" not in cfg: parser.error("This method does not use repulsion")
        if not np.isfinite(args.repulsion_strength) or args.repulsion_strength < 0: parser.error("Repulsion strength must be finite and nonnegative")
        cfg["repulsion_strength"] = args.repulsion_strength
    if args.epochs is not None:
        if args.epochs < 1: parser.error("--epochs must be positive")
        cfg["epochs"] = args.epochs
    cfg["device"] = ("cuda:0" if torch.cuda.is_available() else "cpu") if args.device == "auto" else args.device
    torch.set_num_threads(cfg["cpu_threads"])
    random.seed(cfg["seed"]); np.random.seed(cfg["seed"]); torch.manual_seed(cfg["seed"])
    if torch.cuda.is_available(): torch.cuda.manual_seed_all(cfg["seed"])
    data_path = Path(args.data)
    if not data_path.is_absolute(): data_path = ROOT / data_path
    if not data_path.is_file():
        raise FileNotFoundError(f"Missing {data_path}. Run: python generate_data.py")
    with np.load(data_path, allow_pickle=False) as archive:
        data = {k: archive[k] for k in archive.files}
    for name in ("x_train", "y_train", "x_test", "y_test", "x_grid", "f_grid"):
        if name not in data or data[name].ndim != 2 or data[name].shape[1] != 1 or not np.isfinite(data[name]).all():
            raise ValueError(f"Invalid dataset array: {name}")
    for x, y in (("x_train", "y_train"), ("x_test", "y_test"), ("x_grid", "f_grid")):
        if len(data[x]) != len(data[y]) or len(data[x]) < 2: raise ValueError(f"Invalid lengths: {x}, {y}")
    cfg["data_path"] = str(data_path.resolve())
    cfg["dataset_sha256"] = hashlib.sha256(data_path.read_bytes()).hexdigest()
    cfg["reuse_stage1"] = args.reuse_stage1
    output = Path(args.output)
    if not output.is_absolute(): output = ROOT / output
    if args.output == CONFIG["output_root"]:
        output = output / (METHOD + "_" + datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S_%f"))
    output.mkdir(parents=True, exist_ok=False)
    (output / "config.json").write_text(json.dumps(cfg, indent=2) + "\n")
    return cfg, data, output, torch.device(cfg["device"])


def array(value):
    if isinstance(value, torch.Tensor): value = value.detach().cpu().numpy()
    return np.asarray(value, dtype=np.float64).reshape(-1)


def gaussian_prediction(mean, variance):
    mean, variance = array(mean), array(variance)
    if not np.isfinite(variance).all() or np.any(variance <= 0):
        raise FloatingPointError("Nonpositive or nonfinite predictive variance")
    scale = np.sqrt(variance)
    return dict(mean=mean, scale=scale, lower=mean-1.959963984540054*scale,
                upper=mean+1.959963984540054*scale, family="gaussian", df=None)



def training_clock(device):
    """Wall time with CUDA synchronization, so queued GPU work is counted."""
    if torch.device(device).type == "cuda": torch.cuda.synchronize(device)
    return time.perf_counter()


def record_result(label, test, grid, data, output, cfg, seconds):
    """Score noisy held-out observations and save predictions in original units."""
    from scipy.stats import norm, t
    for prediction, n in ((test, len(data["x_test"])), (grid, len(data["x_grid"]))):
        for key in ("mean", "scale", "lower", "upper"):
            values = array(prediction[key]); prediction[key] = values
            if len(values) != n or not np.isfinite(values).all(): raise FloatingPointError(f"Invalid {label} {key}")
        if np.any(prediction["scale"] <= 0) or np.any(prediction["lower"] > prediction["upper"]):
            raise FloatingPointError(f"Invalid {label} interval/scale")
    target = data["y_test"].reshape(-1)
    distribution = norm if test["family"] == "gaussian" else t
    kwargs = {} if test["family"] == "gaussian" else {"df": test["df"]}
    nll = -distribution.logpdf(target, loc=test["mean"], scale=test["scale"], **kwargs).mean()
    metrics = dict(method=label, rmse=float(np.sqrt(np.mean((target-test["mean"])**2))), nll=float(nll),
                   predictive_family=test["family"], seconds=seconds, dataset_sha256=cfg["dataset_sha256"])
    metrics.update(training_seconds=cfg.get("_training_seconds"),
                   stage1_training_seconds=cfg.get("_stage1_training_seconds"),
                   stage2_training_seconds=cfg.get("_stage2_training_seconds"),
                   training_reused=cfg.get("_training_reused", False))
    if not np.isfinite([metrics["rmse"], metrics["nll"]]).all(): raise FloatingPointError(f"Nonfinite metrics: {label}")
    folder=output / label; folder.mkdir()
    (folder / "metrics.json").write_text(json.dumps(metrics, indent=2) + "\n")
    arrays={}
    for split,pred in (("test",test),("grid",grid)):
        for key in ("mean","scale","lower","upper"): arrays[split+"_"+key]=pred[key]
    arrays.update(x_test=data["x_test"], y_test=data["y_test"], x_grid=data["x_grid"],
                  f_grid=data["f_grid"], df=np.nan if test["df"] is None else test["df"])
    np.savez_compressed(folder / "predictions.npz", **arrays)
    fig,ax=plt.subplots(figsize=(8,4))
    draw_prediction(ax,label,grid,data,metrics)
    fig.tight_layout(); fig.savefig(folder / "prediction.png", dpi=180); plt.close(fig)
    print(f"{label}: RMSE={metrics['rmse']:.5f}, NLL={metrics['nll']:.5f}", flush=True)
    return metrics


def draw_prediction(ax, label, grid, data, metrics):
    x=data["x_grid"].reshape(-1)
    ax.fill_between(x,grid["lower"],grid["upper"],alpha=.22,label="95% predictive interval")
    ax.plot(x,grid["mean"],label="Prediction")
    ax.plot(x,data["f_grid"].reshape(-1),"k--",lw=1,label="True function")
    ax.scatter(data["x_train"],data["y_train"],s=9,c="black",alpha=.45,label="Training data")
    ax.set(xlabel="x",ylabel="y",title=f"{label} | RMSE {metrics['rmse']:.4f} | NLL {metrics['nll']:.4f}",xlim=(float(x.min()),float(x.max())))
    ax.legend(fontsize=7)


def save_history(output, rows):
    if not rows: return
    with (output / "history.csv").open("w",newline="") as handle:
        writer=csv.DictWriter(handle,fieldnames=list(rows[0])); writer.writeheader(); writer.writerows(rows)


def finish(output, rows):
    (output / "metrics.json").write_text(json.dumps(rows,indent=2)+"\n")
    print(f"Saved {output}", flush=True)


def preprocess(data, cfg, device):
    """Original sklearn scaling path: fit on training observations only."""
    sx,sy=StandardScaler(),StandardScaler()
    x={k:data[k].copy() for k in ("x_train","x_test","x_grid")}
    if cfg["normalize_x"]:
        if cfg["x_norm_type"] == "standard":
            sx.fit(x["x_train"])
            x={k:sx.transform(v) for k,v in x.items()}
        elif cfg["x_norm_type"] == "whiten":
            tx=torch.tensor(x["x_train"],dtype=torch.float32,device=device)
            mean,w=whitening_params(tx, eps=cfg["whiten_eps"])
            x={k:clamp_abs_(whiten(torch.tensor(v,dtype=torch.float32,device=device),mean,w),cfg["whiten_max_abs"]).cpu().numpy() for k,v in x.items()}
        else: raise ValueError("x_norm_type must be standard or whiten")
    y=data["y_train"].copy()
    if cfg["normalize_y"]:
        sy.fit(y); y=sy.transform(y); ym,ys=float(sy.mean_[0]),float(sy.scale_[0])
    else: ym,ys=0.,1.
    return ({k:torch.tensor(v,dtype=torch.float32,device=device) for k,v in x.items()},
            torch.tensor(y,dtype=torch.float32,device=device),ym,ys)

# --- Training and comparison entrypoint ---

def main():
    cfg,data,output,device=experiment_setup()
    if cfg["reuse_stage1"]: raise ValueError("--reuse-stage1 is only for deep_ensemble")
    x,y,ym,ys=preprocess(data,cfg,device)
    start=time.perf_counter()
    model=VBLLRegressor(1,cfg["hidden_dim"],cfg["hidden_layers"],getattr(nn,cfg["activation"]),1./len(y),
                        cfg["prior_scale"],cfg["wishart_scale"]).to(device)
    loader=DataLoader(TensorDataset(x["x_train"],y),batch_size=cfg["batch_size"],shuffle=True)
    train_stats=train_one_split(model,loader,x["x_train"],x["x_test"],torch.tensor(data["y_train"],device=device),
        torch.tensor(data["y_test"],device=device),torch.tensor(ym,device=device),torch.tensor(ys,device=device),
        cfg["epochs"],cfg["lr"],cfg["weight_decay"],cfg["clip_val"],
        epoch_eval_csv_path=None,epoch_eval_every_epochs=1)[-1]
    cfg["_training_seconds"]=train_stats["train_seconds"]
    save_history(output,train_stats["training_history"])
    @torch.no_grad()
    def prediction(key):
        model.eval(); pred=model(x[key]).predictive
        mean=pred.mean.squeeze(-1)*ys+ym
        cov=pred.covariance
        var=cov[:,0,0] if cov.dim()==3 else cov.reshape(-1)
        return gaussian_prediction(mean,var.clamp_min(1e-12)*ys**2)
    rows=[record_result(METHOD,prediction("x_test"),prediction("x_grid"),data,output,cfg,time.perf_counter()-start)]
    torch.save(dict(state_dict=model.state_dict(),y_mean=ym,y_std=ys,x_train_model=x["x_train"].cpu()),output / "model.pt")
    finish(output,rows)


if __name__ == "__main__":
    main()
